function credpl_save_credential() {
    if ( ! current_user_can( 'manage_options' ) ) {
        wp_die( esc_html__( 'You do not have permission to do this.', 'credentials-manager' ) );
    }
    check_admin_referer( 'credpl_save_credential' );

    $title = isset( $_POST['title'] ) ? sanitize_text_field( wp_unslash( $_POST['title'] ) ) : '';
    $link  = isset( $_POST['credential_link'] ) ? esc_url_raw( wp_unslash( $_POST['credential_link'] ) ) : '';

    Credpl_Data::insert_credential( array( 'title' => $title, 'credential_link' => $link ) );

    wp_safe_redirect( admin_url( 'admin.php?page=credpl-credentials&saved=1' ) );
    exit;
}
add_action( 'admin_post_credpl_save_credential', 'credpl_save_credential' );
